-- Better Auth tables for Cloudflare D1 (decision 0018, design D6), with the
-- username plugin. The block between the markers is generated by
-- scripts/cloudflare/generate-auth-migration.mjs from the installed
-- better-auth; do not edit it by hand. Better Auth's own queries run inside
-- the library (outside lib/db/scope.ts and the scoped-queries rule).
--
-- User ids are UUIDs (generateId in lib/auth), the same shape as the ids
-- copied from Supabase, so the app tables' user_id keeps its meaning.

-- BEGIN generated by better-auth
create table "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" integer not null, "image" text, "createdAt" date not null, "updatedAt" date not null, "username" text unique, "displayUsername" text);

create table "session" ("id" text not null primary key, "expiresAt" date not null, "token" text not null unique, "createdAt" date not null, "updatedAt" date not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);

create table "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" date, "refreshTokenExpiresAt" date, "scope" text, "password" text, "createdAt" date not null, "updatedAt" date not null);

create table "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);

create index "session_userId_idx" on "session" ("userId");

create index "account_userId_idx" on "account" ("userId");

create index "verification_identifier_idx" on "verification" ("identifier");
-- END generated by better-auth

-- Username format (Postgres usernames table, 035): lower case, 3 to 30 of
-- a-z 0-9 _ -. Null for accounts without a username (GitHub, Google).
CREATE TRIGGER user_username_format_insert
BEFORE INSERT ON "user"
FOR EACH ROW
WHEN NEW.username IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'check_violation: username must be 3 to 30 characters of a-z, 0-9, _ or -')
    WHERE length(NEW.username) NOT BETWEEN 3 AND 30
       OR NEW.username GLOB '*[^a-z0-9_-]*';
END;

CREATE TRIGGER user_username_format_update
BEFORE UPDATE OF username ON "user"
FOR EACH ROW
WHEN NEW.username IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'check_violation: username must be 3 to 30 characters of a-z, 0-9, _ or -')
    WHERE length(NEW.username) NOT BETWEEN 3 AND 30
       OR NEW.username GLOB '*[^a-z0-9_-]*';
END;
